-- Content cell (content), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA content;

CREATE FUNCTION content.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE content.content (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    title                    text NOT NULL CHECK (length(title) >= 1),
    slug                     text,
    content_type             text CHECK (content_type IS NULL OR (content_type IN ('blog', 'newsletter', 'video', 'podcast', 'social', 'course', 'template', 'playbook', 'other'))),
    summary                  text,
    body                     text,
    body_html                text,
    status                   text NOT NULL DEFAULT 'idea' CHECK (status IN ('idea', 'draft', 'review', 'published', 'archived')),
    published_at             timestamptz,
    platforms                text,
    canonical_url            text,
    views                    integer NOT NULL DEFAULT 0,
    shares                   integer NOT NULL DEFAULT 0,
    leads_generated          integer NOT NULL DEFAULT 0,
    meta_title               text,
    meta_description         text,
    keywords                 text,
    related_skill_ids        text,
    related_niche_id         bigint,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX content_legacy ON content.content (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX content_content_type ON content.content (workspace_id, content_type);
CREATE INDEX content_related_niche_id ON content.content (workspace_id, related_niche_id);
CREATE INDEX content_status ON content.content (workspace_id, status);

CREATE TABLE content.content_series_episodes (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    series_slug              text NOT NULL CHECK (length(series_slug) >= 1),
    day_number               integer NOT NULL,
    platform                 text NOT NULL DEFAULT 'tiktok',
    account_handle           text NOT NULL CHECK (length(account_handle) >= 1),
    title                    text,
    topic                    text,
    script_path              text,
    planned_date             date,
    status                   text NOT NULL DEFAULT 'idea' CHECK (status IN ('idea', 'drafting', 'ready_to_record', 'recorded', 'edited', 'approved', 'published_user_confirmed', 'published_verified', 'metrics_reviewed')),
    recorded_at              timestamptz,
    published_at             timestamptz,
    public_url               text,
    evidence_source          text,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX content_series_episodes_legacy ON content.content_series_episodes (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX content_series_episodes_status ON content.content_series_episodes (workspace_id, status);

CREATE TABLE content.content_calendar (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    title                    text NOT NULL CHECK (length(title) >= 1),
    content_type             text NOT NULL DEFAULT 'blog' CHECK (content_type IN ('blog', 'newsletter', 'video', 'podcast', 'social', 'thread', 'carousel', 'course', 'template', 'other')),
    topic                    text,
    angle                    text,
    target_audience          text,
    platform                 text,
    scheduled_date           date,
    published_at             timestamptz,
    status                   text NOT NULL DEFAULT 'idea' CHECK (status IN ('idea', 'researching', 'outlining', 'drafting', 'review', 'scheduled', 'published', 'repurposed', 'killed')),
    priority                 integer NOT NULL DEFAULT 3,
    content_body             text,
    word_count               integer NOT NULL DEFAULT 0,
    has_cta                  boolean NOT NULL DEFAULT false,
    repurpose_from           bigint,
    repurpose_to             text,
    distribution_channels    text,
    views                    integer NOT NULL DEFAULT 0,
    engagement               integer NOT NULL DEFAULT 0,
    leads_generated          integer NOT NULL DEFAULT 0,
    related_project_id       bigint,
    related_skill_ids        text,
    related_content_id       bigint,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, repurpose_from) REFERENCES content.content_calendar (workspace_id, id),
    FOREIGN KEY (workspace_id, related_content_id) REFERENCES content.content (workspace_id, id)
);
CREATE UNIQUE INDEX content_calendar_legacy ON content.content_calendar (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX content_calendar_content_type ON content.content_calendar (workspace_id, content_type);
CREATE INDEX content_calendar_has_cta ON content.content_calendar (workspace_id, has_cta);
CREATE INDEX content_calendar_related_content_id ON content.content_calendar (workspace_id, related_content_id);
CREATE INDEX content_calendar_related_project_id ON content.content_calendar (workspace_id, related_project_id);
CREATE INDEX content_calendar_repurpose_from ON content.content_calendar (workspace_id, repurpose_from);
CREATE INDEX content_calendar_status ON content.content_calendar (workspace_id, status);

CREATE TABLE content.content_series_episode_metrics (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    episode_id               bigint NOT NULL,
    views                    integer,
    likes                    integer,
    comments                 integer,
    shares                   integer,
    saves                    integer,
    profile_views            integer,
    followers                integer,
    captured_at              timestamptz NOT NULL,
    source                   text NOT NULL DEFAULT 'manual',
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, episode_id) REFERENCES content.content_series_episodes (workspace_id, id)
);
CREATE UNIQUE INDEX content_series_episode_metrics_legacy ON content.content_series_episode_metrics (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX content_series_episode_metrics_episode_id ON content.content_series_episode_metrics (workspace_id, episode_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE content.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('content', 'content-calendar', 'content-series-episode', 'content-series-episode-metric')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE content.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON content.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['content', 'content_series_episodes', 'content_calendar', 'content_series_episode_metrics', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE content.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE content.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON content.%I'
                       ' USING (workspace_id = content.current_workspace())'
                       ' WITH CHECK (workspace_id = content.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA content TO content_api;
GRANT EXECUTE ON FUNCTION content.current_workspace() TO content_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON content.content, content.content_series_episodes, content.content_calendar, content.content_series_episode_metrics TO content_api;
GRANT USAGE ON SEQUENCE content.content_id_seq, content.content_series_episodes_id_seq, content.content_calendar_id_seq, content.content_series_episode_metrics_id_seq TO content_api;
GRANT SELECT, INSERT ON content.create_keys TO content_api;
GRANT SELECT, INSERT ON content.outbox TO content_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON content.outbox TO content_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON content.outbox TO content_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA content TO content_publisher;
GRANT SELECT ON content.outbox TO content_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON content.outbox TO content_publisher;
